-- Permission vocabulary and system roles of the subscription module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the subscription permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('subscription:activate'::text, 'subscription'::text, 'activate'::text, 'Activate subscription'::text),
            ('subscription:cancel'::text, 'subscription'::text, 'cancel'::text, 'Cancel subscription'::text),
            ('subscription:create'::text, 'subscription'::text, 'create'::text, 'Create subscription'::text),
            ('subscription:delete'::text, 'subscription'::text, 'delete'::text, 'Delete subscription'::text),
            ('subscription:expire'::text, 'subscription'::text, 'expire'::text, 'Expire subscription'::text),
            ('subscription:mark_past_due'::text, 'subscription'::text, 'mark_past_due'::text, 'Mark past due subscription'::text),
            ('subscription:pause'::text, 'subscription'::text, 'pause'::text, 'Pause subscription'::text),
            ('subscription:purge'::text, 'subscription'::text, 'purge'::text, 'Purge subscription'::text),
            ('subscription:reactivate'::text, 'subscription'::text, 'reactivate'::text, 'Reactivate subscription'::text),
            ('subscription:read'::text, 'subscription'::text, 'read'::text, 'Read subscription'::text),
            ('subscription:restore'::text, 'subscription'::text, 'restore'::text, 'Restore subscription'::text),
            ('subscription:resume'::text, 'subscription'::text, 'resume'::text, 'Resume subscription'::text),
            ('subscription:update'::text, 'subscription'::text, 'update'::text, 'Update subscription'::text),
            ('subscription_billing_run:create'::text, 'subscription_billing_run'::text, 'create'::text, 'Create subscription billing run'::text),
            ('subscription_billing_run:delete'::text, 'subscription_billing_run'::text, 'delete'::text, 'Delete subscription billing run'::text),
            ('subscription_billing_run:fail'::text, 'subscription_billing_run'::text, 'fail'::text, 'Fail subscription billing run'::text),
            ('subscription_billing_run:invoice'::text, 'subscription_billing_run'::text, 'invoice'::text, 'Invoice subscription billing run'::text),
            ('subscription_billing_run:purge'::text, 'subscription_billing_run'::text, 'purge'::text, 'Purge subscription billing run'::text),
            ('subscription_billing_run:read'::text, 'subscription_billing_run'::text, 'read'::text, 'Read subscription billing run'::text),
            ('subscription_billing_run:restore'::text, 'subscription_billing_run'::text, 'restore'::text, 'Restore subscription billing run'::text),
            ('subscription_billing_run:retry'::text, 'subscription_billing_run'::text, 'retry'::text, 'Retry subscription billing run'::text),
            ('subscription_billing_run:update'::text, 'subscription_billing_run'::text, 'update'::text, 'Update subscription billing run'::text),
            ('subscription_plan:archive'::text, 'subscription_plan'::text, 'archive'::text, 'Archive subscription plan'::text),
            ('subscription_plan:create'::text, 'subscription_plan'::text, 'create'::text, 'Create subscription plan'::text),
            ('subscription_plan:delete'::text, 'subscription_plan'::text, 'delete'::text, 'Delete subscription plan'::text),
            ('subscription_plan:purge'::text, 'subscription_plan'::text, 'purge'::text, 'Purge subscription plan'::text),
            ('subscription_plan:read'::text, 'subscription_plan'::text, 'read'::text, 'Read subscription plan'::text),
            ('subscription_plan:restore'::text, 'subscription_plan'::text, 'restore'::text, 'Restore subscription plan'::text),
            ('subscription_plan:update'::text, 'subscription_plan'::text, 'update'::text, 'Update subscription plan'::text),
            ('subscription_plan_line:create'::text, 'subscription_plan_line'::text, 'create'::text, 'Create subscription plan line'::text),
            ('subscription_plan_line:delete'::text, 'subscription_plan_line'::text, 'delete'::text, 'Delete subscription plan line'::text),
            ('subscription_plan_line:purge'::text, 'subscription_plan_line'::text, 'purge'::text, 'Purge subscription plan line'::text),
            ('subscription_plan_line:read'::text, 'subscription_plan_line'::text, 'read'::text, 'Read subscription plan line'::text),
            ('subscription_plan_line:restore'::text, 'subscription_plan_line'::text, 'restore'::text, 'Restore subscription plan line'::text),
            ('subscription_plan_line:update'::text, 'subscription_plan_line'::text, 'update'::text, 'Update subscription plan line'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('subscription:activate'::text, 'subscription'::text, 'activate'::text, 'Activate subscription'::text),
            ('subscription:cancel'::text, 'subscription'::text, 'cancel'::text, 'Cancel subscription'::text),
            ('subscription:create'::text, 'subscription'::text, 'create'::text, 'Create subscription'::text),
            ('subscription:delete'::text, 'subscription'::text, 'delete'::text, 'Delete subscription'::text),
            ('subscription:expire'::text, 'subscription'::text, 'expire'::text, 'Expire subscription'::text),
            ('subscription:mark_past_due'::text, 'subscription'::text, 'mark_past_due'::text, 'Mark past due subscription'::text),
            ('subscription:pause'::text, 'subscription'::text, 'pause'::text, 'Pause subscription'::text),
            ('subscription:purge'::text, 'subscription'::text, 'purge'::text, 'Purge subscription'::text),
            ('subscription:reactivate'::text, 'subscription'::text, 'reactivate'::text, 'Reactivate subscription'::text),
            ('subscription:read'::text, 'subscription'::text, 'read'::text, 'Read subscription'::text),
            ('subscription:restore'::text, 'subscription'::text, 'restore'::text, 'Restore subscription'::text),
            ('subscription:resume'::text, 'subscription'::text, 'resume'::text, 'Resume subscription'::text),
            ('subscription:update'::text, 'subscription'::text, 'update'::text, 'Update subscription'::text),
            ('subscription_billing_run:create'::text, 'subscription_billing_run'::text, 'create'::text, 'Create subscription billing run'::text),
            ('subscription_billing_run:delete'::text, 'subscription_billing_run'::text, 'delete'::text, 'Delete subscription billing run'::text),
            ('subscription_billing_run:fail'::text, 'subscription_billing_run'::text, 'fail'::text, 'Fail subscription billing run'::text),
            ('subscription_billing_run:invoice'::text, 'subscription_billing_run'::text, 'invoice'::text, 'Invoice subscription billing run'::text),
            ('subscription_billing_run:purge'::text, 'subscription_billing_run'::text, 'purge'::text, 'Purge subscription billing run'::text),
            ('subscription_billing_run:read'::text, 'subscription_billing_run'::text, 'read'::text, 'Read subscription billing run'::text),
            ('subscription_billing_run:restore'::text, 'subscription_billing_run'::text, 'restore'::text, 'Restore subscription billing run'::text),
            ('subscription_billing_run:retry'::text, 'subscription_billing_run'::text, 'retry'::text, 'Retry subscription billing run'::text),
            ('subscription_billing_run:update'::text, 'subscription_billing_run'::text, 'update'::text, 'Update subscription billing run'::text),
            ('subscription_plan:archive'::text, 'subscription_plan'::text, 'archive'::text, 'Archive subscription plan'::text),
            ('subscription_plan:create'::text, 'subscription_plan'::text, 'create'::text, 'Create subscription plan'::text),
            ('subscription_plan:delete'::text, 'subscription_plan'::text, 'delete'::text, 'Delete subscription plan'::text),
            ('subscription_plan:purge'::text, 'subscription_plan'::text, 'purge'::text, 'Purge subscription plan'::text),
            ('subscription_plan:read'::text, 'subscription_plan'::text, 'read'::text, 'Read subscription plan'::text),
            ('subscription_plan:restore'::text, 'subscription_plan'::text, 'restore'::text, 'Restore subscription plan'::text),
            ('subscription_plan:update'::text, 'subscription_plan'::text, 'update'::text, 'Update subscription plan'::text),
            ('subscription_plan_line:create'::text, 'subscription_plan_line'::text, 'create'::text, 'Create subscription plan line'::text),
            ('subscription_plan_line:delete'::text, 'subscription_plan_line'::text, 'delete'::text, 'Delete subscription plan line'::text),
            ('subscription_plan_line:purge'::text, 'subscription_plan_line'::text, 'purge'::text, 'Purge subscription plan line'::text),
            ('subscription_plan_line:read'::text, 'subscription_plan_line'::text, 'read'::text, 'Read subscription plan line'::text),
            ('subscription_plan_line:restore'::text, 'subscription_plan_line'::text, 'restore'::text, 'Restore subscription plan line'::text),
            ('subscription_plan_line:update'::text, 'subscription_plan_line'::text, 'update'::text, 'Update subscription plan line'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
